<template>
  <div class="space-y-6">
    <PageHeader title="入站" parent="代理" description="配置用户接入与内部中转，保存后创建配置版本并发布。"><template #actions><button @click="openCreate" class="ios-btn-primary">创建入站</button><button @click="revision" :disabled="!nodeId" class="ios-btn-secondary disabled:opacity-40">生成节点配置版本</button></template></PageHeader>
    <div class="flex items-center gap-3">
      <span class="text-xs font-medium text-ios-secondary">所属节点</span>
      <select v-model="nodeId" @change="page = 1; load()" class="ios-filter-select">
        <option value="">全部节点</option>
        <option v-for="node in nodes" :key="node.id" :value="node.id">{{ node.name }}</option>
      </select>
    </div>
    <ErrorState v-if="error" :message="error" @retry="load" /><EmptyState v-else-if="!inbounds.length" title="暂无入站" />
    <DataTable v-else><template #header><th>名称</th><th>节点</th><th>协议 / 监听</th><th>用途</th><th>默认出站</th><th>状态</th><th>操作</th></template><template #body><tr v-for="inbound in inbounds" :key="inbound.id"><td class="p-4 font-semibold">{{ inbound.name }}</td><td>{{ nodes.find(node => node.id === inbound.nodeId)?.name || inbound.nodeId }}</td><td class="text-xs">{{ inbound.protocol }} · {{ inbound.listen }}:{{ inbound.port }}<p>{{ inbound.protocol==='wireguard' ? '原生加密 / UDP' : (inbound.settings.security || 'none') + ' / ' + (inbound.settings.transport || 'tcp') }}</p></td><td class="text-xs">{{ inbound.internalRelay ? '内部中转' : '用户接入' }}<p>{{ inbound.subscriptionVisible ? '订阅可见' : '订阅隐藏' }}</p></td><td class="text-xs">{{ outboundName(inbound.defaultOutbound) }}</td><td><StatusBadge :status="inbound.enabled ? 'active' : 'disabled'" /></td><td class="space-x-2"><button @click="openEdit(inbound)" class="ios-action-btn-primary">编辑</button><button @click="target = inbound; confirmVisible = true" class="ios-action-btn-danger">删除</button></td></tr></template><template #footer><Pagination :total="total" :current-page="page" :page-size="20" @update:page="changePage" /></template></DataTable>
    <FormDrawer v-model="drawer" :title="editing ? '编辑入站' : '创建入站'" :loading="saving" @confirm="save" confirm-text="保存草稿">
      <div class="space-y-4 text-sm">
        <label class="block">名称<input v-model="form.name" maxlength="40" class="form-input-base mt-2" /></label>
        <label class="block">节点<select v-model="form.nodeId" :disabled="!!editing" class="form-input-base mt-2"><option value="">请选择</option><option v-for="node in nodes" :key="node.id" :value="node.id">{{ node.name }}</option></select></label>
        <label class="block">协议<select v-model="form.protocol" :disabled="!!editing" @change="protocolChanged" class="form-input-base mt-2"><option v-for="protocol in protocolOptions.inbound" :key="protocol">{{ protocol }}</option></select></label>
        <p v-if="form.protocol==='wireguard'" class="text-xs text-gray-500">WireGuard使用原生加密和UDP接入。只有节点报告支持WireGuard入站时才能发布；保存草稿不会立即启用。</p>
        <p v-if="form.protocol==='wireguard' && form.nodeId" class="text-xs" :class="nodes.find(node=>node.id===form.nodeId)?.capabilities?.protocols?.some(protocol=>protocol.protocol==='wireguard' && protocol.inbound) ? 'text-green-700' : 'text-amber-700'">{{ nodes.find(node=>node.id===form.nodeId)?.capabilities?.protocols?.some(protocol=>protocol.protocol==='wireguard' && protocol.inbound) ? '所选节点已报告支持WireGuard入站，发布时仍会校验当前能力。' : '所选节点尚未报告支持WireGuard入站，请先核对节点与核心能力。' }}</p>
        <label class="block">监听地址<input v-model="form.listen" class="form-input-base mt-2" /></label><label class="block">端口<input v-model.number="form.port" type="number" min="1" max="65535" class="form-input-base mt-2" /></label>
        <label class="block"><input v-model="form.internalRelay" :disabled="!!editing" type="checkbox" /> 内部中转入口</label><label v-if="!form.internalRelay" class="block"><input v-model="form.subscriptionVisible" type="checkbox" /> 显示在授权用户订阅中</label>
        <label class="block">默认出站<select v-model="form.defaultOutbound" class="form-input-base mt-2"><option value="direct">Direct</option><option value="block">Block</option><option v-for="outbound in outbounds.filter(item => item.nodeId === form.nodeId && item.enabled)" :key="outbound.id" :value="outbound.id">{{ outbound.name }}</option><option v-for="group in outboundGroups.filter(item => item.nodeId === form.nodeId && item.enabled)" :key="group.id" :value="'group:' + group.id">出口组 · {{ group.name }}</option><option v-for="chain in chains.filter(item => item.nodeIds[0] === form.nodeId && item.enabled)" :key="chain.id" :value="'chain:' + chain.id">代理链 · {{ chain.name }}</option></select></label>
        <div v-if="!form.internalRelay" class="space-y-1.5"><div class="flex items-center justify-between"><label class="text-xs font-medium text-ios-secondary">允许用户</label><span class="text-[11px] text-ios-tertiary">不勾选表示组内全部授权用户</span></div><div class="rounded-2xl p-3 bg-[#F5F5F7] border border-black/[0.06]"><div v-if="users.length" class="space-y-1.5 max-h-40 overflow-y-auto pr-1 scrollbar-thin"><label v-for="user in users" :key="user.id" :class="['flex items-center justify-between p-2 rounded-xl text-xs cursor-pointer select-none transition-all', form.allowedUserIds.includes(user.id) ? 'bg-white text-ios-label font-medium shadow-2xs border border-ios-blue/30' : 'bg-white/60 text-ios-secondary hover:bg-white hover:text-ios-label border border-transparent']"><div class="flex items-center gap-2.5 min-w-0 flex-1 truncate"><div :class="['w-4 h-4 rounded-md flex items-center justify-center transition-all shrink-0', form.allowedUserIds.includes(user.id) ? 'bg-ios-blue text-white' : 'border border-[#C7C7CC] bg-white']"><svg v-if="form.allowedUserIds.includes(user.id)" class="w-3 h-3" viewBox="0 0 20 20" fill="currentColor"><path fill-rule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clip-rule="evenodd" /></svg></div><span class="truncate">{{ user.username }}</span></div><input v-model="form.allowedUserIds" type="checkbox" :value="user.id" class="sr-only" /></label></div><p v-else class="text-xs text-ios-tertiary py-1">暂无用户</p></div></div>
        <template v-if="form.protocol !== 'wireguard'">
          <label v-if="!['hysteria2','tuic'].includes(form.protocol)" class="block">传输<select v-model="form.settings.transport" class="form-input-base mt-2"><option value="tcp">TCP</option><option value="ws">WebSocket</option><option value="grpc">gRPC</option></select></label>
          <label class="block">安全方式<select v-model="form.settings.security" class="form-input-base mt-2"><option v-if="!['trojan','hysteria2','tuic'].includes(form.protocol)" value="none">None</option><option value="tls">TLS</option></select></label>
          <label v-if="form.settings.transport === 'ws'" class="block">WebSocket 路径<input v-model="form.settings.path" class="form-input-base mt-2" /></label><label v-if="form.settings.transport === 'grpc'" class="block">gRPC 服务名称<input v-model="form.settings.service_name" class="form-input-base mt-2" /></label>
          <template v-if="form.settings.security === 'tls'"><label class="block">服务器名称<input v-model="form.settings.server_name" class="form-input-base mt-2" /></label><p v-if="form.internalRelay" class="text-xs text-gray-500">内部 TLS 证书由系统生成并固定信任。也可提供自有证书。</p><label class="block">证书 PEM<textarea v-model="form.settings.certificate_pem" rows="4" class="form-input-base mt-2 font-mono text-xs"></textarea></label><label class="block">私钥 PEM<textarea v-model="form.settings.private_key_pem" rows="4" :placeholder="editing?.hasTlsKey ? '留空保留现有私钥' : ''" class="form-input-base mt-2 font-mono text-xs"></textarea></label></template>
          <template v-if="form.settings.quic"><p class="text-xs text-gray-500">使用原生 QUIC 与 TLS，需要支持该协议的 sing-box 节点。</p><template v-if="form.protocol === 'hysteria2'"><label class="block">上传带宽 Mbps（0 使用默认）<input v-model.number="form.settings.quic.up_mbps" type="number" min="0" max="100000" class="form-input-base mt-2" /></label><label class="block">下载带宽 Mbps（0 使用默认）<input v-model.number="form.settings.quic.down_mbps" type="number" min="0" max="100000" class="form-input-base mt-2" /></label></template><label v-if="form.protocol === 'tuic'" class="block">拥塞控制<select v-model="form.settings.quic.congestion_control" class="form-input-base mt-2"><option value="">默认</option><option value="cubic">cubic</option><option value="new_reno">new_reno</option><option value="bbr">bbr</option></select></label></template>
          <label v-if="form.protocol === 'shadowsocks'" class="block">加密方式<select v-model="form.settings.method" class="form-input-base mt-2"><option>chacha20-ietf-poly1305</option><option>aes-256-gcm</option><option>aes-128-gcm</option></select></label>
        </template>
        <template v-else><label class="block">隧道地址<textarea v-model="wireguardAddresses" rows="3" placeholder="10.77.0.1/24&#10;fd77::1/64" class="form-input-base mt-2 font-mono"></textarea></label><label class="block">MTU<input v-model.number="wireguardMTU" type="number" min="576" max="9000" class="form-input-base mt-2" /></label><p class="text-xs text-gray-500">每行一个接口地址，每个地址族的首个子网用于自动分配。服务端密钥由系统生成；用户公钥按授权设备展开。</p><p v-if="form.internalRelay" class="text-xs text-gray-500">保存时同步关联中转的地址、端口和公钥草稿。请生成相关节点配置版本，并先发布目标节点，再发布源节点。</p></template>
        <label class="block"><input v-model="form.enabled" type="checkbox" /> 启用</label><p class="text-xs text-gray-500">保存后不会立即修改节点。请生成配置版本，并先发布中转目标，再发布入口节点。</p>
      </div>
    </FormDrawer>
    <ConfirmDialog v-model="confirmVisible" title="删除入站草稿" :message="`删除 ${target?.name || ''}？运行配置需重新发布；被中转引用的入站不能删除。`" @confirm="remove" />
  </div>
</template>
<script setup lang="ts">
import { ref, reactive, onMounted, watch } from 'vue'; import { useRouter } from 'vue-router'; import { proxyAPI, protocolOptions, loadProtocolSupport, type Inbound, type InboundInput, type Outbound, type OutboundGroup, type ProxyChain, choices } from '../api'; import { request, type Page } from '../../../app/apiClient'; import { type NodeView } from '../../nodes/api'; import { userAPI, type ProxyUser } from '../../users/api'; import { showToast } from '../../../app/api'; import PageHeader from '../../../components/PageHeader.vue'; import DataTable from '../../../components/DataTable.vue'; import StatusBadge from '../../../components/StatusBadge.vue'; import Pagination from '../../../components/Pagination.vue'; import FormDrawer from '../../../components/FormDrawer.vue'; import ConfirmDialog from '../../../components/ConfirmDialog.vue'; import ErrorState from '../../../components/ErrorState.vue'; import EmptyState from '../../../components/EmptyState.vue';
const outboundGroups = ref<OutboundGroup[]>([]); const chains = ref<ProxyChain[]>([]); const router = useRouter(); const inbounds = ref<Inbound[]>([]); const outbounds = ref<Outbound[]>([]); const nodes = ref<NodeView[]>([]); const users = ref<ProxyUser[]>([]); const nodeId = ref(''); const page = ref(1); const total = ref(0); const error = ref(''); const drawer = ref(false); const saving = ref(false); const editing = ref<Inbound | null>(null); const target = ref<Inbound | null>(null); const confirmVisible = ref(false); const wireguardAddresses = ref('10.77.0.1/24'); const wireguardMTU = ref(1420);
function defaults(): InboundInput { return { name: '', nodeId: nodeId.value, protocol: 'socks5', listen: '0.0.0.0', port: 1080, enabled: true, subscriptionVisible: true, internalRelay: false, defaultOutbound: 'direct', allowedUserIds: [], settings: { transport: 'tcp', security: 'none' } }; }
const form = reactive<InboundInput>(defaults());
function outboundName(id: string) { return id === 'direct' ? 'Direct' : id === 'block' ? 'Block' : outbounds.value.find(item => item.id === id)?.name || outboundGroups.value.find(item => 'group:' + item.id === id)?.name || chains.value.find(item => 'chain:' + item.id === id)?.name || id; }
async function load() { try { const [result, outs, ns, us, gs, cs] = await Promise.all([proxyAPI.inbounds(nodeId.value, page.value), proxyAPI.outbounds('', 1, 100), request<Page<NodeView>>('/nodes?page=1&pageSize=100'), userAPI.list(1, '', 100), choices((p,s) => proxyAPI.groups('',p,s)), choices((p,s) => proxyAPI.chains('',p,s))]); inbounds.value = result.items; total.value = result.total; outbounds.value = outs.items; nodes.value = ns.items; users.value = us.items; outboundGroups.value = gs; chains.value = cs; error.value = ''; } catch (e) { error.value = (e as Error).message; } }
function changePage(value: number) { page.value = value; load(); } function openCreate() { editing.value = null; Object.assign(form, defaults()); wireguardAddresses.value = '10.77.0.1/24'; wireguardMTU.value = 1420; drawer.value = true; }
function openEdit(inbound: Inbound) { editing.value = inbound; Object.assign(form, { name: inbound.name, nodeId: inbound.nodeId, protocol: inbound.protocol, listen: inbound.listen, port: inbound.port, enabled: inbound.enabled, subscriptionVisible: inbound.subscriptionVisible, internalRelay: inbound.internalRelay, defaultOutbound: inbound.defaultOutbound, allowedUserIds: [...inbound.allowedUserIds], settings: JSON.parse(JSON.stringify(inbound.settings)) }); wireguardAddresses.value = inbound.settings.wireguard?.addresses.join('\n') || '10.77.0.1/24'; wireguardMTU.value = inbound.settings.wireguard?.mtu || 1420; drawer.value = true; }
function protocolChanged() { form.settings = form.protocol === 'wireguard' ? {} : { transport: ['hysteria2','tuic'].includes(form.protocol) ? 'quic' : 'tcp', quic: ['hysteria2','tuic'].includes(form.protocol) ? {} : undefined, security: ['trojan','hysteria2','tuic'].includes(form.protocol) ? 'tls' : 'none', method: form.protocol === 'shadowsocks' ? 'chacha20-ietf-poly1305' : undefined }; }
async function save() { if (saving.value) return; saving.value = true; try { const value = JSON.parse(JSON.stringify(form)) as InboundInput; if (value.internalRelay) value.subscriptionVisible = false; if (value.protocol === 'wireguard') value.settings = { wireguard: { secret_key: '', addresses: wireguardAddresses.value.split(/\r?\n/).map(value => value.trim()).filter(Boolean), peers: value.settings.wireguard?.peers || [], mtu: wireguardMTU.value } }; await proxyAPI.saveInbound(editing.value?.id || null, value); drawer.value = false; showToast(value.protocol === 'wireguard' && value.internalRelay ? '入站及关联中转草稿已保存，请发布相关节点配置版本' : '入站草稿已保存'); await load(); } catch (e) { showToast((e as Error).message, 'error'); } finally { saving.value = false; } }
async function remove() { if (!target.value) return; try { await proxyAPI.deleteInbound(target.value.id); showToast('入站已删除'); await load(); } catch (e) { showToast((e as Error).message, 'error'); } }
async function revision() { if (!nodeId.value) return; try { await proxyAPI.revision(nodeId.value, '更新节点入站与出站'); await router.push('/system/revisions'); } catch (e) { showToast((e as Error).message, 'error'); } }
watch(drawer, visible => { if (!visible) form.settings.private_key_pem = ''; }); onMounted(() => { loadProtocolSupport(); load(); });
</script>
